            (function(n){
    var v = n.value; if(!v) return [{desc:"输入颜色值或预设名"}];
    if(/^\s*\d+\s*,\s*\d+\s*,\s*\d+/.test(v)) return [{value:v}];
    if(/^#[0-9a-fA-F]{6,8}$/.test(v)) return [{value:v}];
    return [{value:v, desc:"CustomColor预设名"}];
})

